#include <stdio.h>
#include <stdbool.h>
#include <stdlib.h>

static long long dist2(const int a[2], const int b[2]) {
    long long dx = (long long)a[0] - b[0];
    long long dy = (long long)a[1] - b[1];
    return dx * dx + dy * dy;
}

static void sort6(long long a[6]) {
    for (int i = 1; i < 6; ++i) {
        long long x = a[i];
        int j = i - 1;
        while (j >= 0 && a[j] > x) {
            a[j + 1] = a[j];
            --j;
        }
        a[j + 1] = x;
    }
}

bool validSquare(int* p1, int p1Size, int* p2, int p2Size,
                 int* p3, int p3Size, int* p4, int p4Size) {
    (void)p1Size; (void)p2Size; (void)p3Size; (void)p4Size;
    int* p[4] = {p1, p2, p3, p4};
    long long d[6];
    int k = 0;
    for (int i = 0; i < 4; ++i)
        for (int j = i + 1; j < 4; ++j)
            d[k++] = dist2(p[i], p[j]);
